import html

def sanitize_input(value):
    """Sanitize user input to safely handle special characters.

    Strips leading/trailing whitespace, escapes HTML special characters,
    and ensures the value is a safe string.
    """
    if value is None:
        return ""
    # Normalize unicode characters to their composed form
    import unicodedata
    value = unicodedata.normalize('NFKC', value)
    # Escape HTML entities to prevent XSS
    value = html.escape(value)
    return value.strip()

